properties.query:
let alertWindow = 15m;
let minSpeed = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'MinGroundspeed_ms'
    | project toreal(Value));
// AOI 박스 3개를 개별 scalar로 추출 (Watch List 행 수 고정 가정)
let aoi1MinLat = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_recon' | project toreal(MinLat));
let aoi1MaxLat = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_recon' | project toreal(MaxLat));
let aoi1MinLon = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_recon' | project toreal(MinLon));
let aoi1MaxLon = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_recon' | project toreal(MaxLon));
let aoi2MinLat = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_attack' | project toreal(MinLat));
let aoi2MaxLat = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_attack' | project toreal(MaxLat));
let aoi2MinLon = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_attack' | project toreal(MinLon));
let aoi2MaxLon = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_attack' | project toreal(MaxLon));
let aoi3MinLat = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_escort' | project toreal(MinLat));
let aoi3MaxLat = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_escort' | project toreal(MaxLat));
let aoi3MinLon = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_escort' | project toreal(MinLon));
let aoi3MaxLon = toscalar(_GetWatchlist('AOI_Boundary_List') | where MissionId == 'mpd_escort' | project toreal(MaxLon));
UAVTelemetry_CL
| where TimeGenerated > ago(alertWindow)
| where MsgType == 'GLOBAL_POSITION_INT'
| where Groundspeed_ms > minSpeed
| where isnotnull(Lat) and isnotnull(Lon)
| extend InAoi1 = Lat >= aoi1MinLat and Lat <= aoi1MaxLat and Lon >= aoi1MinLon and Lon <= aoi1MaxLon
| extend InAoi2 = Lat >= aoi2MinLat and Lat <= aoi2MaxLat and Lon >= aoi2MinLon and Lon <= aoi2MaxLon
| extend InAoi3 = Lat >= aoi3MinLat and Lat <= aoi3MaxLat and Lon >= aoi3MinLon and Lon <= aoi3MaxLon
| where not(InAoi1) and not(InAoi2) and not(InAoi3)
| summarize ExcursionCount=count(), FirstSeen=min(TimeGenerated), AvgLat=avg(Lat), AvgLon=avg(Lon)
    by UAVId, bin(TimeGenerated, 5m)
| where ExcursionCount >= 3
| extend TriggerReason = strcat("AOI_이탈_", tostring(ExcursionCount), "회_UAVId:", UAVId)
| extend Severity = "Medium"
| project FirstSeen, UAVId, ExcursionCount, AvgLat, AvgLon, TriggerReason, Severity
| order by FirstSeen desc
